MutantDict = Annotated[dict[str, Callable], "Mutant"]


def _mutmut_trampoline(orig, mutants, call_args, call_kwargs, self_arg = None):
    """Forward call to original or mutated function, depending on the environment"""
    import os
    mutant_under_test = os.environ['MUTANT_UNDER_TEST']
    if mutant_under_test == 'fail':
        from mutmut.__main__ import MutmutProgrammaticFailException
        raise MutmutProgrammaticFailException('Failed programmatically')      
    elif mutant_under_test == 'stats':
        from mutmut.__main__ import record_trampoline_hit
        record_trampoline_hit(orig.__module__ + '.' + orig.__name__)
        result = orig(*call_args, **call_kwargs)
        return result
    prefix = orig.__module__ + '.' + orig.__name__ + '__mutmut_'
    if not mutant_under_test.startswith(prefix):
        result = orig(*call_args, **call_kwargs)
        return result
    mutant_name = mutant_under_test.rpartition('.')[-1]
    if self_arg is not None:
        # call to a class method where self is not bound
        result = mutants[mutant_name](self_arg, *call_args, **call_kwargs)
    else:
        result = mutants[mutant_name](*call_args, **call_kwargs)
    return result


class SmellSeverity(Enum):
    """Code smell severity levels."""

    INFO = "info"
    WARNING = "warning"
    ERROR = "error"
    CRITICAL = "critical"


class SmellCategory(Enum):
    """Code smell categories."""

    COMPLEXITY = "complexity"
    NAMING = "naming"
    STRUCTURE = "structure"
    DUPLICATION = "duplication"
    MAINTAINABILITY = "maintainability"
    SECURITY = "security"


@dataclass
class CodeSmell:
    """Detected code smell."""

    rule_id: str
    message: str
    severity: SmellSeverity
    category: SmellCategory
    file_path: Path
    line_start: int
    line_end: int
    suggestion: Optional[str] = None
    metadata: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        """Serialize to dictionary."""
        return {
            "rule_id": self.rule_id,
            "message": self.message,
            "severity": self.severity.value,
            "category": self.category.value,
            "file": str(self.file_path),
            "line_start": self.line_start,
            "line_end": self.line_end,
            "suggestion": self.suggestion,
            "metadata": self.metadata,
        }


@dataclass
class SmellRule:
    """Code smell detection rule."""

    rule_id: str
    name: str
    description: str
    severity: SmellSeverity
    category: SmellCategory
    detector: Callable[[ast.AST, Path], list[CodeSmell]]
    enabled: bool = True


class CodeSmellDetector:
    """Detects code smells in Python source code.

    Configurable rules engine supporting:
    - Built-in rules (complexity, naming, structure)
    - Custom rule registration
    - Severity filtering
    - Category filtering
    """

    # Thresholds
    MAX_FUNCTION_LENGTH = 50
    MAX_FUNCTION_ARGS = 5
    MAX_NESTED_DEPTH = 4
    MAX_CYCLOMATIC_COMPLEXITY = 10
    MIN_NAME_LENGTH = 2
    MAX_NAME_LENGTH = 40

