    def xǁCodeSmellDetectorǁ_detect_deep_nesting__mutmut_orig(
        self, tree: ast.AST, file_path: Path
    ) -> list[CodeSmell]:
        """Detect deeply nested code blocks."""
        smells = []

        def check_depth(node: ast.AST, depth: int = 0):
            # Increment depth for control structures
            nesting_nodes = (
                ast.If,
                ast.For,
                ast.While,
                ast.With,
                ast.Try,
                ast.ExceptHandler,
            )
            if isinstance(node, nesting_nodes):
                depth += 1
                if depth > self.MAX_NESTED_DEPTH:
                    smells.append(
                        CodeSmell(
                            rule_id="SMELL-C003",
                            message=f"Code is nested {depth} levels deep (max: {self.MAX_NESTED_DEPTH})",
                            severity=SmellSeverity.WARNING,
                            category=SmellCategory.COMPLEXITY,
                            file_path=file_path,
                            line_start=node.lineno,
                            line_end=getattr(node, "end_lineno", node.lineno),
                            suggestion="Consider early returns or extracting helper functions",
                            metadata={"depth": depth},
                        )
                    )

            for child in ast.iter_child_nodes(node):
                check_depth(child, depth)

        check_depth(tree)
        return smells

