    def xǁCodeSmellDetectorǁ_detect_god_class__mutmut_orig(
        self, tree: ast.AST, file_path: Path
    ) -> list[CodeSmell]:
        """Detect classes with too many methods (God Class anti-pattern)."""
        smells = []
        max_methods = 20

        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                method_count = sum(
                    1
                    for child in node.body
                    if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
                )

                if method_count > max_methods:
                    smells.append(
                        CodeSmell(
                            rule_id="SMELL-S001",
                            message=f"Class '{node.name}' has {method_count} methods (max: {max_methods})",
                            severity=SmellSeverity.ERROR,
                            category=SmellCategory.STRUCTURE,
                            file_path=file_path,
                            line_start=node.lineno,
                            line_end=getattr(node, "end_lineno", node.lineno),
                            suggestion="Consider splitting into smaller, focused classes",
                            metadata={"method_count": method_count, "class": node.name},
                        )
                    )
        return smells

